insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1616','6-81',1616,'渗透','shèntòu','Thẩm thấu, thấm vào','这些信息已经渗透到各个角落。','Zhèxiē xìnxī yǐjīng shèntòu dào gège jiǎoluò.','Những thông tin này đã thấm vào mọi ngóc ngách.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1617','6-81',1617,'慎重','shènzhòng','Cẩn trọng','我们需要慎重考虑。','Wǒmen xūyào shènzhòng kǎolǜ.','Chúng ta cần cân nhắc thận trọng.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1618','6-81',1618,'牲畜','shēngchù','Gia súc','这个农场有很多牲畜。','Zhège nóngchǎng yǒu hěnduō shēngchù.','Trang trại này có nhiều gia súc.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1619','6-81',1619,'生存','shēngcún','Sinh tồn','动物在野外生存很困难。','Dòngwù zài yěwài shēngcún hěn kùnnán.','Động vật sống sót ngoài tự nhiên rất khó khăn.');
