insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1621','6-82',1621,'生理','shēnglǐ','Sinh lý','生理健康非常重要。','Shēnglǐ jiànkāng fēicháng zhòngyào.','Sức khỏe sinh lý rất quan trọng.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1622','6-82',1622,'声明','shēngmíng','Tuyên bố','公司发布了一项重要声明。','Gōngsī fābù le yī xiàng zhòngyào shēngmíng.','Công ty đã đưa ra một thông báo quan trọng.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1623','6-82',1623,'声势','shēngshì','Thanh thế','他的声势越来越大。','Tā de shēngshì yuè lái yuè dà.','Thanh thế của anh ấy ngày càng lớn.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1624','6-82',1624,'生疏','shēngshū','Lạ lẫm, không quen thuộc','他对新环境感到生疏。','Tā duì xīn huánjìng gǎndào shēngshū.','Anh ấy cảm thấy lạ lẫm với môi trường mới.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1625','6-82',1625,'生态','shēngtài','Sinh thái','保护生态环境很重要。','Bǎohù shēngtài huánjìng hěn zhòngyào.','Bảo vệ môi trường sinh thái rất quan trọng.');
