insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1627','6-82',1627,'生效','shēngxiào','Có hiệu lực','这项法律开始生效。','Zhè xiàng fǎlǜ kāishǐ shēngxiào.','Luật này bắt đầu có hiệu lực.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1628','6-82',1628,'生锈','shēngxiù','Bị gỉ sét','铁会在潮湿的环境中生锈。','Tiě huì zài cháoshī de huánjìng zhōng shēngxiù.','Sắt sẽ bị rỉ sét trong môi trường ẩm ướt.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1629','6-82',1629,'生育','shēngyù','Sinh sản','计划生育政策在中国很普遍。','Jìhuà shēngyù zhèngcè zài Zhōngguó hěn pǔbiàn.','Chính sách kế hoạch hóa gia đình rất phổ biến ở Trung Quốc.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1630','6-82',1630,'声誉','shēngyù','Danh tiếng','他在国际上享有很高的声誉。','Tā zài guójì shàng xiǎngyǒu hěn gāo de shēngyù.','Anh ấy có danh tiếng cao trên thế giới.');
