insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1632','6-82',1632,'盛产','shèngchǎn','Sản xuất nhiều, phong phú','这个地区盛产水果。','Zhège dìqū shèngchǎn shuǐguǒ.','Khu vực này nổi tiếng về sản xuất trái cây.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1633','6-82',1633,'胜负','shèngfù','Thắng thua','比赛结果取决于胜负。','Bǐsài jiéguǒ qǔjué yú shèngfù.','Kết quả trận đấu phụ thuộc vào thắng thua.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1634','6-82',1634,'盛开','shèngkāi','Nở rộ','春天，花朵盛开。','Chūntiān, huāduǒ shèngkāi.','Mùa xuân, hoa nở rộ.');
