insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1637','6-82',1637,'师范','shīfàn','Sư phạm','他在师范学校学习。','Tā zài shīfàn xuéxiào xuéxí.','Anh ấy học ở trường sư phạm.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1638','6-82',1638,'施加','shījiā','Áp đặt, tác động','我们必须施加压力。','Wǒmen bìxū shījiā yālì.','Chúng ta phải gây áp lực.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1639','6-82',1639,'尸体','shītǐ','Thi thể','他们找到了尸体。','Tāmen zhǎodào le shītǐ.','Họ đã tìm thấy thi thể.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1640','6-82',1640,'失误','shīwù','Sai lầm, lỗi lầm','他的演讲中有几次失误。','Tā de yǎnjiǎng zhōng yǒu jǐ cì shīwù.','Trong bài phát biểu của anh ấy có vài lỗi.');
