insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1645','6-83',1645,'识别','shíbié','Nhận biết, phân biệt','这种花很容易识别。','Zhè zhǒng huā hěn róngyì shíbié.','Loại hoa này rất dễ nhận biết.');
