insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1647','6-83',1647,'时常','shícháng','Thường xuyên','她时常去健身房锻炼。','Tā shícháng qù jiànshēnfáng duànliàn.','Cô ấy thường xuyên đi tập gym.');
