insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1649','6-83',1649,'时光','shíguāng','Thời gian','时光飞逝，我们已经毕业了。','Shíguāng fēishì, wǒmen yǐjīng bìyè le.','Thời gian trôi nhanh, chúng ta đã tốt nghiệp rồi.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1650','6-83',1650,'实惠','shíhuì','Giá trị thực, có lợi ích thực sự','这家餐厅提供实惠的午餐。','Zhè jiā cāntīng tígōng shíhuì de wǔcān.','Nhà hàng này cung cấp bữa trưa giá rẻ.');
