insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1653','6-83',1653,'实施','shíshī','Thực thi, thực hiện','政府计划实施新政策。','Zhèngfǔ jìhuà shíshī xīn zhèngcè.','Chính phủ dự định thực hiện chính sách mới.');
