insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1658','6-83',1658,'时装','shízhuāng','Thời trang','她喜欢穿时装。','Tā xǐhuān chuān shízhuāng.','Cô ấy thích mặc trang phục thời trang.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1659','6-83',1659,'十足','shízú','Đầy đủ, hoàn toàn','他的解释十足有力。','Tā de jiěshì shízú yǒulì.','Lời giải thích của anh ấy rất thuyết phục.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1660','6-83',1660,'使命','shǐmìng','Sứ mệnh','我们的使命是保护环境。','Wǒmen de shǐmìng shì bǎohù huánjìng.','Sứ mệnh của chúng tôi là bảo vệ môi trường.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1661','6-84',1661,'势必','shìbì','Chắc chắn','他势必会成功。','Tā shìbì huì chénggōng.','Anh ấy chắc chắn sẽ thành công.');
