insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1663','6-84',1663,'示范','shìfàn','Làm mẫu, mô phỏng','老师示范了如何解决这个问题。','Lǎoshī shìfàn le rúhé jiějué zhège wèntí.','Giáo viên đã làm mẫu cách giải quyết vấn đề này.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1664','6-84',1664,'释放','shìfàng','Giải phóng','他被释放了。','Tā bèi shìfàng le.','Anh ấy đã được thả.');
