insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1666','6-84',1666,'事故','shìgù','Sự cố','事故发生后，交通被封闭了。','Shìgù fāshēng hòu, jiāotōng bèi fēngbì le.','Sau khi tai nạn xảy ra, giao thông đã bị phong tỏa.');
