insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1668','6-84',1668,'事件','shìjiàn','Sự kiện','这次事件引起了广泛关注。','Zhè cì shìjiàn yǐnqǐ le guǎngfàn guānzhù.','Sự kiện này đã thu hút sự quan tâm rộng rãi.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1669','6-84',1669,'世界观','shìjièguān','Thế giới quan','每个人都有不同的世界观。','Měi gèrén dōu yǒu bùtóng de shìjièguān.','Mỗi người có một thế giới quan khác nhau.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1670','6-84',1670,'视力','shìlì','Thị lực','他的视力很好。','Tā de shìlì hěn hǎo.','Thị lực của anh ấy rất tốt.');
